   397	   */
   398	  hwp_sdmmc1->CLKCR = SD_CLKCR_STOP_CLK;
   399	  HAL_Delay_us(10);
   400	  hwp_sdmmc1->CLKCR = ((div - 1) << SD_CLKCR_DIV_Pos) | SD_CLKCR_VOID_FIFO_ERROR | SD_CLKCR_STOP_CLK;
