   545	  uint32_t mhz;
   546	
   547	  if (g_sd_baremetal)
   548	    {
   549	      /* PRIMASK 挡住 SysTick ISR，不能用 clock_systime。DWT 仍在走。 */
   550	      hclk = HAL_RCC_GetHCLKFreq(CORE_ID_HCPU);
   551	      mhz = (hclk >= 1000000u) ? (hclk / 1000000u) : 240u;
   552	      return (uint64_t)((*(volatile uint32_t *)0xe0001004u) / mhz);
   553	    }
   554	
   555	  clock_systime_timespec(&ts);
   556	  return (uint64_t)ts.tv_sec * 1000000ull + (uint64_t)(ts.tv_nsec / 1000);
   557	}
