   559	/*
   560	 * 当前块 I/O 调用的**绝对截止时刻**（0 = 不限）。
   561	 *
   562	 * 光在重试之间查预算不够：一次 mute 读的耗时大头在**底层收尾**里 ——
   563	 * `stop:` 分支的 CMD12 + `sd1_recover_after_error()`（内含 1×CMD12 +
   564	 * 3×(CMD13+CMD12)），以及解卡里的 `sd1_wait_dat0(2 s)`。这些都要用同一个
   565	 * deadline 截断，读才有真正的墙钟上限（Codex R1/R2 P1-3）。
   566	 *
   567	 * 只在 `bread` / `bwrite` / `erase` 这三个块 I/O 入口设置与清除；`g_sd_lock`
   568	 * 保证同一时刻只有一个持有者，所以单变量足够。
   569	 */
   570	static uint64_t g_sd_deadline_us;
   571	
   572	static void sd1_deadline_set(uint32_t budget_us)
   573	{
   574	  g_sd_deadline_us = sd1_mono_us() + budget_us;
   575	}
   576	
   577	static void sd1_deadline_clear(void)
   578	{
   579	  g_sd_deadline_us = 0;
   580	}
   581	
   582	/** 把一次等待截到剩余预算（没有预算时原样返回）。 */
   583	static uint64_t sd1_deadline_cap(uint64_t timeout_us)
   584	{
   585	  uint64_t now;
   586	  uint64_t left;
   587	
   588	  if (g_sd_deadline_us == 0)
   589	    {
   590	      return timeout_us;
   591	    }
   592	
   593	  now = sd1_mono_us();
   594	  if (now >= g_sd_deadline_us)
   595	    {
   596	      return 1;
   597	    }
   598	
   599	  left = g_sd_deadline_us - now;
   600	  return left < timeout_us ? left : timeout_us;
   601	}
   602	
   603	/** 预算是否已经用光（无预算时恒 false）。 */
   604	static bool sd1_deadline_passed(void)
   605	{
   606	  return g_sd_deadline_us != 0 && sd1_mono_us() >= g_sd_deadline_us;
   607	}
