   609	/*
   610	 * 记录一次失败时的 SR。**第一次**失败的值单独保存在 `g_sd_call_first_sr`：
   611	 * 后面的 CMD12/解卡会覆盖 `g_sd_last_sr`，判死日志要报的是原始故障
   612	 *（Codex R3/R4 P2-R1-10）。
   613	 */
   614	static void sd1_note_fail_sr(uint32_t sr)
   615	{
   616	  g_sd_last_sr = sr;
   617	
   618	  if (g_sd_call_first_valid)
   619	    {
   620	      return;
   621	    }
   622	
   623	  g_sd_call_first_sr = sr;
   624	  g_sd_call_first_valid = true;
   625	}
