   636	/* Clear command flags only.  Boot never writes SR before CCR; HAL_SDMMC_SET_CMD
   637	 * also wipes DATA_* which races sd1_setup_read() (DPSM already running).
   638	 */
   639	
   640	static void sd1_clr_cmd_int(void)
   641	{
   642	  hwp_sdmmc1->SR = SD_SR_CMD_DONE | SD_SR_CMD_RSP_CRC | SD_SR_CMD_TIMEOUT |
   643	                   SD_SR_CMD_SENT;
   644	}
   645	
   646	static uint8_t sd1_wait_cmd(void)
   647	{
   648	  /* 单条命令的应答也要受块 I/O 预算约束：mute 卡上第一次 CMD17 就等满
   649	   * 50 ms，四次重试光这一项就是 200 ms（Codex R3 P1-3）。 */
   650	  uint64_t deadline = sd1_mono_us() + sd1_deadline_cap(SF32LB_SD_WAIT_US);
   651	
   652	  while ((hwp_sdmmc1->SR & (SD_SR_CMD_DONE | SD_SR_CMD_TIMEOUT)) == 0)
   653	    {
   654	      if (sd1_mono_us() >= deadline)
   655	        {
   656	          sd1_note_fail_sr(hwp_sdmmc1->SR);
   657	          hwp_sdmmc1->SR = 0xffffffff;
   658	          g_sd_diag.cmd_timeout++;
   659	          return SD_TIMEOUT;
   660	        }
   661	    }
   662	
   663	  hwp_sdmmc1->SR = SD_SR_CMD_DONE;
   664	  if (hwp_sdmmc1->SR & SD_SR_CMD_TIMEOUT)
   665	    {
   666	      sd1_note_fail_sr(hwp_sdmmc1->SR);
   667	      g_sd_diag.cmd_timeout++;
   668	      return SD_TIMEOUT;
   669	    }
   670	
   671	  if (hwp_sdmmc1->SR & SD_SR_CMD_RSP_CRC)
   672	    {
   673	      return SD_CRCERR;
   674	    }
   675	
   676	  return SD_SUCCESS;
   677	}
   678	
   679	static uint8_t sd1_send_cmd(uint8_t cmd_idx, uint32_t cmd_arg)
   680	{
   681	  uint32_t ccr;
   682	  uint8_t has_rsp;
   683	  uint8_t long_rsp;
   684	
   685	  sd1_clr_cmd_int();
   686	  hwp_sdmmc1->CAR = cmd_arg;
   687	  switch (cmd_idx)
   688	    {
   689	      case 2:
   690	      case 9:
   691	      case 10:
   692	        has_rsp = 1;
   693	        long_rsp = 1;
   694	        break;
   695	      case 0:
   696	      case 4:
   697	      case 15:
   698	        has_rsp = 0;
   699	        long_rsp = 0;
   700	        break;
   701	      default:
   702	        has_rsp = 1;
   703	        long_rsp = 0;
   704	        break;
   705	    }
   706	
   707	  ccr = (cmd_idx << SD_CCR_CMD_INDEX_Pos);
   708	  if (has_rsp)
   709	    {
   710	      ccr |= SD_CCR_CMD_HAS_RSP;
   711	    }
   712	
   713	  if (long_rsp)
   714	    {
   715	      ccr |= SD_CCR_CMD_LONG_RSP;
   716	    }
   717	
   718	  ccr |= SD_CCR_CMD_TX_EN | SD_CCR_CMD_START;
   719	  hwp_sdmmc1->CCR = ccr;
   720	  return sd1_wait_cmd();
   721	}
   722	
   723	static uint8_t sd1_send_acmd(uint8_t cmd_idx, uint32_t cmd_arg, uint16_t rca)
   724	{
   725	  uint32_t ccr;
   726	  uint8_t cmd_result;
   727	
   728	  cmd_result = sd1_send_cmd(55, (uint32_t)rca << 16);
   729	  if (cmd_result != SD_SUCCESS)
   730	    {
   731	      return cmd_result;
   732	    }
   733	
   734	  hwp_sdmmc1->CAR = cmd_arg;
   735	  ccr = (cmd_idx << SD_CCR_CMD_INDEX_Pos) | SD_CCR_CMD_HAS_RSP;
   736	  ccr |= SD_CCR_CMD_TX_EN | SD_CCR_CMD_START;
   737	  hwp_sdmmc1->CCR = ccr;
   738	  cmd_result = sd1_wait_cmd();
   739	  if ((cmd_result == SD_CRCERR) && (cmd_idx == 41)) /* no CRC check for R3 */
   740	    {
   741	      hwp_sdmmc1->SR = SD_SR_CMD_RSP_CRC;
   742	      cmd_result = SD_SUCCESS;
   743	    }
   744	
   745	  return cmd_result;
   746	}
