   748	static void sd1_get_rsp(uint8_t *rsp_idx, uint32_t *a1, uint32_t *a2,
   749	                        uint32_t *a3, uint32_t *a4)
   750	{
   751	  *rsp_idx = hwp_sdmmc1->RIR;
   752	  *a1 = hwp_sdmmc1->RAR1;
   753	  *a2 = hwp_sdmmc1->RAR2;
   754	  *a3 = hwp_sdmmc1->RAR3;
   755	  *a4 = hwp_sdmmc1->RAR4;
   756	}
