   758	static void sd1_setup_read(uint8_t wire_mode, uint8_t block_num)
   759	{
   760	  uint32_t dcr;
   761	
   762	  hwp_sdmmc1->DLR = (SD_HW_BLOCK_SIZE * block_num) - 1;
   763	  dcr = ((SD_HW_BLOCK_SIZE - 1) << SD_DCR_BLOCK_SIZE_Pos);
   764	  dcr |= (wire_mode << SD_DCR_WIRE_MODE_Pos) | SD_DCR_R_WN;
   765	  dcr |= SD_DCR_TRAN_DATA_EN | SD_DCR_DATA_START;
   766	  hwp_sdmmc1->DCR = dcr;
   767	}
   768	
   769	static uint8_t sd1_wait_read(void)
   770	{
   771	  uint32_t mask = SD_SR_DATA_DONE | SD_SR_DATA_TIMEOUT | SD_SR_DATA_CRC |
   772	                  SD_SR_FIFO_OVERRUN;
   773	  uint64_t deadline = sd1_mono_us() + sd1_deadline_cap(SF32LB_SD_WAIT_US);
   774	
   775	  while ((hwp_sdmmc1->SR & mask) == 0)
   776	    {
   777	      if (sd1_mono_us() >= deadline)
   778	        {
   779	          hwp_sdmmc1->SR = 0xffffffff;
   780	          g_sd_diag.rd_timeout++;
   781	          return SD_TIMEOUT;
   782	        }
   783	    }
   784	
   785	  hwp_sdmmc1->SR = SD_SR_DATA_DONE;
   786	  if (hwp_sdmmc1->SR & SD_SR_DATA_TIMEOUT)
   787	    {
   788	      g_sd_diag.rd_timeout++;
   789	      return SD_TIMEOUT;
   790	    }
   791	
   792	  if (hwp_sdmmc1->SR & (SD_SR_DATA_CRC | SD_SR_FIFO_OVERRUN))
   793	    {
   794	      g_sd_diag.rd_crc++;
   795	      return SD_CRCERR;
   796	    }
   797	
   798	  return SD_SUCCESS;
   799	}
   800	
   801	static void sd1_setup_write(uint8_t wire_mode, uint8_t block_num)
   802	{
   803	  uint32_t dcr;
   804	
   805	  hwp_sdmmc1->DLR = (SD_HW_BLOCK_SIZE * block_num) - 1;
   806	  dcr = ((SD_HW_BLOCK_SIZE - 1) << SD_DCR_BLOCK_SIZE_Pos);
   807	  dcr |= (wire_mode << SD_DCR_WIRE_MODE_Pos);
   808	  dcr |= SD_DCR_TRAN_DATA_EN | SD_DCR_DATA_START;
   809	  hwp_sdmmc1->DCR = dcr;
   810	}
   811	
   812	/* DSR[0] is DAT0 last-level.  After a write the card holds DAT0 low while
   813	 * it programs; SD_SR_DATA_BUSY is only the host TX engine.  Identify samples
   814	 * idle DAT0 — if it is not high, skip this poll so a dead DSR cannot stall
   815	 * every block for WRITE_MAX_US.
   816	 */
   817	
   818	static bool sd1_dat0_ready(void)
   819	{
   820	  if (!g_sd_dat0_poll)
   821	    {
   822	      return true;
   823	    }
   824	
   825	  return (hwp_sdmmc1->DSR & 1u) != 0;
   826	}
   827	
   828	/**
   829	 * @brief PIO 忙等循环的“让出 + 喂狗”节拍器，每 1 ms 触发一次。
   830	 *
   831	 * @details
   832	 * 下面几个等待都是**轮询卡的状态位**（等 DAT0 编程忙、等 DATA_DONE、
   833	 * 等 DATA_BUSY），没有中断可用，所以轮询耗掉的时间必然记在发起 I/O 的那个
   834	 * 线程头上 —— 这不是"等"、是实打实的 CPU。
   835	 *
   836	 * 原先只有 `sd1_wait_dat0()` 会 `sched_yield()` + 喂狗，而
   837	 * `sd1_wait_write()` / `sd1_wait_card_idle()` 是**纯自旋**，上界
   838	 * `SF32LB_SD_WRITE_MAX_US` = 2 s。调用者优先级高于被饿住的那些任务时，
   839	 * 这 2 s 里它们一个都跑不到 —— 具体到本板：diag 线程 pri=9 每 500 ms 往
   840	 * SD 上的 LittleFS 刷日志（`myvendor_diaglog_flush()`），卡一慢就会把
   841	 * `ble_companion`(pri=8) 和 IDLE(0) 饿住。三个等待统一走这个节拍器。
   842	 *
   843	 * @param[in,out] next_yield 下次让出的时刻；调用方进入循环前初始化一次。
   844	 */
   845	static void sd1_spin_yield(uint64_t *next_yield)
   846	{
   847	  uint64_t now = sd1_mono_us();
   848	
   849	  if (now >= *next_yield)
   850	    {
   851	      myvendor_watchdog_work_beat();
   852	      sched_yield();
   853	      *next_yield = now + 1000u;
   854	    }
   855	}
   856	
   857	static uint8_t sd1_wait_dat0(uint64_t timeout_us)
   858	{
   859	  uint64_t deadline;
   860	  uint64_t next_yield;
   861	
   862	  if (!g_sd_dat0_poll)
   863	    {
   864	      return SD_SUCCESS;
   865	    }
   866	
   867	  deadline = sd1_mono_us() + sd1_deadline_cap(timeout_us);
   868	  next_yield = sd1_mono_us() + 1000u;
   869	  while (!sd1_dat0_ready())
   870	    {
   871	      uint64_t now = sd1_mono_us();
   872	
   873	      if (now >= deadline)
   874	        {
   875	          sd1_note_fail_sr(hwp_sdmmc1->SR);
   876	          g_sd_diag.dat0_to++;
   877	          return SD_TIMEOUT;
   878	        }
   879	
   880	      sd1_spin_yield(&next_yield);
   881	    }
   882	
   883	  return SD_SUCCESS;
   884	}
   885	
   886	static uint8_t sd1_wait_write(void)
   887	{
   888	  /* Must wait on the error bits too, not just DATA_DONE: on a write CRC or
   889	   * data timeout the controller may never assert DATA_DONE, which previously
   890	   * spun this loop forever and hung the whole SD-backed filesystem.
   891	   */
   892	
   893	  uint32_t mask = SD_SR_DATA_DONE | SD_SR_DATA_TIMEOUT | SD_SR_DATA_CRC |
   894	                  SD_SR_FIFO_UNDERRUN;
   895	  uint64_t deadline = sd1_mono_us() + sd1_deadline_cap(SF32LB_SD_WRITE_MAX_US);
   896	  uint64_t next_yield = sd1_mono_us() + 1000u;
   897	
   898	  while ((hwp_sdmmc1->SR & mask) == 0)
   899	    {
   900	      if (sd1_mono_us() >= deadline)
   901	        {
   902	          sd1_note_fail_sr(hwp_sdmmc1->SR);
   903	          hwp_sdmmc1->DCR = 0;
   904	          hwp_sdmmc1->SR = 0xffffffff;
   905	          g_sd_diag.wr_timeout++;
   906	          return SD_TIMEOUT;
   907	        }
   908	
   909	      /* 没有这句就是纯自旋最长 2 s：优先级低于调用者的任务全被饿住。 */
   910	      sd1_spin_yield(&next_yield);
   911	    }
   912	
   913	  hwp_sdmmc1->SR = SD_SR_DATA_DONE;
   914	  if (hwp_sdmmc1->SR & SD_SR_DATA_TIMEOUT)
   915	    {
   916	      sd1_note_fail_sr(hwp_sdmmc1->SR);
   917	      g_sd_diag.wr_timeout++;
   918	      return SD_TIMEOUT;
   919	    }
   920	
   921	  if (hwp_sdmmc1->SR & (SD_SR_DATA_CRC | SD_SR_FIFO_UNDERRUN))
   922	    {
   923	      sd1_note_fail_sr(hwp_sdmmc1->SR);
   924	      g_sd_diag.wr_crc++;
   925	      return SD_CRCERR;
   926	    }
   927	
   928	  if (sd1_wait_card_idle() != SD_SUCCESS)
   929	    {
   930	      return SD_TIMEOUT;
   931	    }
   932	
   933	  return sd1_wait_dat0(SF32LB_SD_WRITE_MAX_US);
   934	}
   935	
   936	/* SiFli RT-Thread drv_sdio.c waits SD_SR_DATA_BUSY (HW_SDIO_IT_TXACT) after
   937	 * every data transfer.  That bit is the host data engine, not card DAT0.
   938	 * After it clears, sd1_wait_dat0() waits for programming busy.
   939	 */
   940	
   941	#define SF32LB_SD_BUSY_US  SF32LB_SD_WRITE_MAX_US
   942	
   943	static uint8_t sd1_wait_card_idle(void)
   944	{
   945	  uint64_t deadline = sd1_mono_us() + sd1_deadline_cap(SF32LB_SD_BUSY_US);
   946	  uint64_t next_yield = sd1_mono_us() + 1000u;
   947	
   948	  while ((hwp_sdmmc1->SR & SD_SR_DATA_BUSY) != 0)
   949	    {
   950	      if (sd1_mono_us() >= deadline)
   951	        {
   952	          return SD_TIMEOUT;
   953	        }
   954	
   955	      /* 同上：没有这句就是纯自旋最长 2 s。 */
   956	      sd1_spin_yield(&next_yield);
   957	    }
   958	
   959	  return SD_SUCCESS;
   960	}
   961	
   962	/* 有序停机：先把 SD 时钟停下来、把卡送回 IDLE，然后才允许断外设时钟。
   963	 * 直接拉 ENR2 会把正在移位的 SDCLK 生硬截断，SD-NAND 会锁死到掉电为止
   964	 * （症状：CMD13 无应答 → mute，之后每次重识别 CMD8 都超时、mute_n 一直涨，
   965	 *  只有整机复位才恢复）。顺序照抄 bootloader 的 sd_release()。
   966	 *
   967	 * STOP_CLK=1 才是停钟（HAL_SDMMC_CLK_SET 的 en=0 分支），所以这里绝不能
   968	 * 写 CLKCR=0 —— 那只是把 DIV 清零、时钟照跑。
   969	 */
   970	static void sd1_hw_quiet(void)
   971	{
   972	  hwp_sdmmc1->DCR = 0;
   973	  hwp_sdmmc1->IER = 0;
   974	  hwp_sdmmc1->SR = 0xffffffff;
   975	  (void)sd1_wait_card_idle();
   976	  (void)sd1_send_cmd(0, 0);  /* CMD0 需要时钟，必须放在停钟之前 */
   977	  HAL_Delay_us(1000);
   978	  hwp_sdmmc1->CLKCR = SD_CLKCR_STOP_CLK;  /* 停 SDCLK；此后才允许断外设时钟 */
   979	  HAL_Delay_us(10);
   980	}
